const test = require('node:test');
const assert = require('node:assert/strict');
const { currencyPrecision } = require('../src/currency-precision.cjs');

test("default precision follows the currency minor unit", () => {
  assert.deepEqual(currencyPrecision('USD'), {minimum: 2, maximum: 2});
  assert.deepEqual(currencyPrecision('JPY'), {minimum: 0, maximum: 0});
});

test("minimum precision also raises the implicit maximum when necessary", () => {
  assert.deepEqual(currencyPrecision('USD', 4), {minimum: 4, maximum: 4});
  assert.deepEqual(currencyPrecision('JPY', 1), {minimum: 1, maximum: 1});
  assert.deepEqual(currencyPrecision('USD', 0), {minimum: 0, maximum: 2});
});

