function currencyPrecision(currency, minimumFractionDigits) {
  const formatter = new Intl.NumberFormat('en-US', {
    style: 'currency', currency, minimumFractionDigits
  });
  const options = formatter.resolvedOptions();
  return { minimum: options.minimumFractionDigits, maximum: options.maximumFractionDigits };
}
module.exports = { currencyPrecision };
